cd $D
run() { TAG=$1 SEED=31415 BIN=$B CONDS=1.5,2.0 N=48 W=5 EXTRA="{$X$H$RW$2}" python3 jrand.py; }
run RF3X ',"JUMP_VX_TAB":"1.0:0.10,1.5:0.12,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0045,2.0:0.018","STANCE_TRUNK_YAW":"10","MU_TORSION":"0.02","JUMP_H_NAT_XY":"1","JUMP_TURN_FREE_YAW":"1"'"$TU" &
