run RM5X ',"JUMP_VX_TAB":"1.0:0.10,1.5:0.12,2.0:0.48","JUMP_LEAN_TAB":"1.0:0,1.5:0.0045,2.0:0.018","STANCE_TRUNK_YAW":"10","MU_TORSION":"0.02","JUMP_H_NAT_XY":"1"'"$TU"',"T":"20","JUMP_REPEAT":"4"' &
